39	const PROCESSING_FEE = 5;
40	const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;
41	
42	const percentOf = (amount: number, percent: number): number =>
43	  (amount * percent) / 100;
44	
45	const BASE_PREMIUM_BY_ITEM_TYPE = {
46	  sword: 100,
47	  amulet: 60,
48	  staff: 80,
49	  potion: 40,
50	  rune: 25,
51	  moonstone: 25,
52	} as const satisfies Record<string, number>;
53	
54	type InsurableItemType = keyof typeof BASE_PREMIUM_BY_ITEM_TYPE;
55	
56	const BLOCK_SIZE = 3;
57	const BLOCK_BASE_PREMIUM = 60;
58	const CURSE_SURCHARGE_PERCENT = 50;
59	const HIGH_ENCHANTMENT_THRESHOLD = 5;
60	const HIGH_ENCHANTMENT_SURCHARGE_PERCENT = 30;
61	const LOYALTY_THRESHOLD_YEARS = 2;
62	const LOYALTY_DISCOUNT_PERCENT = 20;
63	
64	const basePremiumOf = (item: Item): number =>
65	  BASE_PREMIUM_BY_ITEM_TYPE[item.type as InsurableItemType];
66	
67	interface RiskSurcharge {
68	  appliesTo: (item: Item) => boolean;
69	  percent: number;
70	}
71	
72	const RISK_SURCHARGES: RiskSurcharge[] = [
73	  { appliesTo: (item) => item.cursed === true, percent: CURSE_SURCHARGE_PERCENT },
74	  {
75	    appliesTo: (item) => (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD,
76	    percent: HIGH_ENCHANTMENT_SURCHARGE_PERCENT,
77	  },
78	];
79	
80	const itemSurcharge = (item: Item): number =>
81	  RISK_SURCHARGES.filter((surcharge) => surcharge.appliesTo(item)).reduce(
82	    (sum, surcharge) => sum + percentOf(basePremiumOf(item), surcharge.percent),
83	    0,
84	  );
85	
86	const policySurcharges = (items: Item[]): number =>
87	  items.reduce((sum, item) => sum + itemSurcharge(item), 0);
88	
89	const groupByType = (items: Item[]): Item[][] => [
90	  ...items
91	    .reduce(
92	      (groups, item) =>
93	        groups.set(item.type, [...(groups.get(item.type) ?? []), item]),
94	      new Map<string, Item[]>(),
95	    )
96	    .values(),
97	];
98	
99	const basePremiumOfGroup = (group: Item[]): number =>
100	  group.length === BLOCK_SIZE
101	    ? BLOCK_BASE_PREMIUM
102	    : group.reduce((sum, item) => sum + basePremiumOf(item), 0);
103	
104	const policyBasePremium = (items: Item[]): number =>
105	  groupByType(items).reduce((sum, group) => sum + basePremiumOfGroup(group), 0);
106	
107	const isLoyal = (customer: Customer): boolean =>
108	  customer.yearsWithMHPCO >= LOYALTY_THRESHOLD_YEARS;
109	
110	const quotePremium = (items: Item[], customer: Customer): number => {
111	  const policyBase = policyBasePremium(items);
112	  const loyaltyDiscount = isLoyal(customer)
113	    ? percentOf(policyBase, LOYALTY_DISCOUNT_PERCENT)
114	    : 0;
115	  const premiumBeforeFee =
116	    policyBase +
117	    policySurcharges(items) -
118	    loyaltyDiscount +
119	    percentOf(policyBase, FIRST_INSURANCE_SURCHARGE_PERCENT);
120	  return Math.ceil(premiumBeforeFee + PROCESSING_FEE);
121	};
122	
123	const runStep = (step: Step, customer: Customer): StepResult => {
124	  if (step.op === "quote")
125	    return { premium: quotePremium(step.items, customer) };
126	  throw new Error("claim steps are not implemented yet");
127	};
128	
129	export const runScenario = (scenario: Scenario): ScenarioResult => ({
130	  results: scenario.steps.map((step) => runStep(step, scenario.customer)),
131	});
