input.new_string:
const isLoyal = (customer: Customer): boolean =>
  customer.yearsWithMHPCO >= LOYALTY_THRESHOLD_YEARS;

interface PolicyAdjustment {
  appliesTo: (customer: Customer) => boolean;
  percent: number;
}

const POLICY_ADJUSTMENTS: PolicyAdjustment[] = [
  { appliesTo: () => true, percent: FIRST_INSURANCE_SURCHARGE_PERCENT },
  { appliesTo: isLoyal, percent: -LOYALTY_DISCOUNT_PERCENT },
];

const policyAdjustments = (policyBase: number, customer: Customer): number =>
  POLICY_ADJUSTMENTS.filter((adjustment) => adjustment.appliesTo(customer)).reduce(
    (sum, adjustment) => sum + percentOf(policyBase, adjustment.percent),
    0,
  );

const quotePremium = (items: Item[], customer: Customer): number => {
  const policyBase = policyBasePremium(items);
  const premiumBeforeFee =
    policyBase + policySurcharges(items) + policyAdjustments(policyBase, customer);
  return Math.ceil(premiumBeforeFee + PROCESSING_FEE);
};
